class Printer {
    public void output() {
        System.out.println("Outputting physical ink on paper...");
    }
}

class ScreenDisplay {
    public void output() {
        System.out.println("Outputting digital pixels on screen...");
    }
}

// IF JAVA ALLOWED THIS (HYPOTHETICAL):
// class Console extends Printer, ScreenDisplay {
//     // No output() method written here
// }

// What would happen if we executed:
// Console c = new Console();
// c.output(); // Does it print paper or pixels? The compiler cannot guess!

public class AmbiguityDemo {
    public static void main(String[] args) {
        System.out.println("Java prevents multiple class inheritance to avoid ambiguity!");
        System.out.println("Every Java class extends at most ONE direct superclass.");
    }
}

class AudioPlayer {
    public void playSound(String track) {
        System.out.println("Playing audio track: " + track);
    }
}

class VideoRecorder {
    public void recordClip(int seconds) {
        System.out.println("Recording " + seconds + " seconds of HD video.");
    }
}

// Instead of extending both, SmartCamera HAS-A AudioPlayer and VideoRecorder!
class SmartCamera {
    private AudioPlayer audio = new AudioPlayer();
    private VideoRecorder video = new VideoRecorder();

    public void captureEvent(String track, int seconds) {
        audio.playSound(track);
        video.recordClip(seconds);
        System.out.println("Event captured successfully without any inheritance conflict!");
    }
}

public class CompositionDemo {
    public static void main(String[] args) {
        SmartCamera camera = new SmartCamera();
        camera.captureEvent("Chime.mp3", 15);
    }
}

