class Heater {
    void heat() {
        System.out.println("Heating activated.");
    }
}

class Cooler {
    void cool() {
        System.out.println("Cooling activated.");
    }
}

class SmartThermostat {
    private Heater heater = new Heater();
    private Cooler cooler = new Cooler();

    void turnOnHeat() {
        heater.heat();
    }

    void turnOnCool() {
        cooler.cool();
    }
}

public class Main {
    public static void main(String[] args) {
        SmartThermostat st = new SmartThermostat();
        st.turnOnHeat();
        st.turnOnCool();
    }
}

class PrinterModule {
    void printDoc(String text) {
        System.out.println("Printing: " + text);
    }
}

class ScannerModule {
    void scanDoc(String title) {
        System.out.println("Scanning: " + title);
    }
}

class OfficeMachine {
    private PrinterModule printer = new PrinterModule();
    private ScannerModule scanner = new ScannerModule();

    void doPrint(String doc) {
        printer.printDoc(doc);
    }

    void doScan(String doc) {
        scanner.scanDoc(doc);
    }
}

public class Main {
    public static void main(String[] args) {
        OfficeMachine machine = new OfficeMachine();
        machine.doPrint("Invoice.pdf");
        machine.doScan("Receipt.jpg");
    }
}

class GPS {
    void navigate(String dest) {
        System.out.println("Navigating to: " + dest);
    }
}

class MusicPlayer {
    void playSong(String title) {
        System.out.println("Playing: " + title);
    }
}

class DashboardConsole {
    private GPS gps = new GPS();
    private MusicPlayer player = new MusicPlayer();

    void startTrip(String destination, String song) {
        gps.navigate(destination);
        player.playSong(song);
    }
}

public class Main {
    public static void main(String[] args) {
        DashboardConsole console = new DashboardConsole();
        console.startTrip("Grand Canyon", "RoadTripJam.mp3");
    }
}

