class MechanicalArm {
    void moveArm() {
        System.out.println("Arm moving to target coordinates.");
    }
}

class SensorArray {
    void readDistance() {
        System.out.println("Sensor reading: 45 cm distance.");
    }
}

class Robot {
    private MechanicalArm arm = new MechanicalArm();
    private SensorArray sensor = new SensorArray();

    void executeTask() {
        sensor.readDistance();
        arm.moveArm();
    }
}

public class Main {
    public static void main(String[] args) {
        Robot bot = new Robot();
        bot.executeTask();
    }
}

class CameraSystem {
    void enableCameras() {
        System.out.println("Cameras streaming live video.");
    }
}

class DoorLockSystem {
    void lockAllDoors() {
        System.out.println("All perimeter doors locked.");
    }
}

class AlarmSiren {
    void armSiren() {
        System.out.println("Motion alarm siren armed.");
    }
}

class HomeSecurityHub {
    private CameraSystem cameras = new CameraSystem();
    private DoorLockSystem doors = new DoorLockSystem();
    private AlarmSiren siren = new AlarmSiren();

    public void activateNightMode() {
        cameras.enableCameras();
        doors.lockAllDoors();
        siren.armSiren();
        System.out.println("Night mode security active.");
    }
}

public class Main {
    public static void main(String[] args) {
        HomeSecurityHub hub = new HomeSecurityHub();
        hub.activateNightMode();
    }
}
